// 1. Получение URL иконки погоды
export const getWeatherIconUrl = (iconCode) => {
  return `https://openweathermap.org/img/wn/${iconCode}@2x.png`;
};

// 2. Вырезание породы собаки из ссылки и форматирование (убираем лишние слэши)
export const formatBreedName = (imgUrl) => {
  if (!imgUrl) return "Pet";
  const breedRaw = imgUrl.split("/")[4]; 
  return breedRaw
    .split("-")
    .reverse()
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
};