// Текущая дата для Hero
export const getHeroDate = () => {
  return new Date().toLocaleDateString("en-US", {
    month: "long",
    year: "numeric",
    weekday: "long",
    day: "numeric",
  });
};

// Время города с учетом сдвига timezone (в секундах) для WeatherCard
export const getCityTime = (timezoneOffset) => {
  const localDate = new Date(Date.now() + timezoneOffset * 1000);
  return localDate.toUTCString().slice(17, 22);
};

// Дата и день недели для WeatherCard
export const getCityDateDetails = (timezoneOffset) => {
  const localDate = new Date(Date.now() + timezoneOffset * 1000);
  return {
    fullDate: localDate.toLocaleDateString(),
    dayName: localDate.toLocaleDateString("en-US", { weekday: "long" })
  };
};

// Форматирование времени для графиков (WeatherChart)
export const formatChartHour = (timestamp) => {
  return new Date(timestamp * 1000).getHours() + ":00";
};

// Форматирование даты для WeeklyForecast
export const formatWeeklyDate = (timestamp) => {
  return new Date(timestamp * 1000).toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
  });
};