import React, { useState } from "react";
import InputField from "./InputField";
import Button from "../ui/Button";

const AuthModal = ({ isLogin, setIsLogin, onSubmit, onClose }) => {
  const [form, setForm] = useState({ username: "", email: "", password: "" });
  const [errors, setErrors] = useState({});

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const validate = () => {
    const errs = {};
    if (!isLogin) {
      if (form.username.length < 3) errs.username = "Too short (min 3)";
      if (/\d/.test(form.username)) errs.username = "No numbers allowed";
    }
    if (!/^[A-Za-z0-9._%+-]{5,}@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(form.email)) errs.email = "Invalid email";
    if (!/^[A-Za-z0-9]{8,}$/.test(form.password)) errs.password = "Min 8 charts";
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!isLogin && !validate()) return;
    onSubmit(form);
  };

  return (
    <div className="modal-backdrop" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal-content">
        
        <button type="button" className="close-modal-btn" onClick={onClose} aria-label="Close modal">
          &times;
        </button>

        <h3 className="modal-title">{isLogin ? "Log In" : "Sign Up"}</h3>
        <form className="header-form" onSubmit={handleSubmit}>
          {!isLogin && (
            <InputField id="username" name="username" label="Username" placeholder="Enter username" value={form.username} onChange={handleChange} error={errors.username} />
          )}
          <InputField id="email" name="email" label="E-Mail" placeholder="Enter email" value={form.email} onChange={handleChange} error={errors.email} />
          <InputField id="password" name="password" type="password" label="Password" placeholder="Enter password" value={form.password} onChange={handleChange} error={errors.password} />
          
          <Button type="submit" className="modal-header-button">
            {isLogin ? "Log In" : "Register"}
          </Button>
        </form>
        <p className="have-account" onClick={() => setIsLogin(!isLogin)} style={{ cursor: "pointer", marginTop: "15px" }}>
          {isLogin ? "No account? Sign Up" : "Already have account? Log In"}
        </p>
      </div>
    </div>
  );
};

export default AuthModal;